def P(t,sty='Bodyx'): return Paragraph(t,S[sty])
def bullet(t): return P('&bull;&nbsp; '+t)
def sec(title,intro=None):
    a=[P(title,'H1x'),HRFlowable(width='100%',thickness=1,color=SURFACE,spaceAfter=7)]
    if intro:a.append(P(intro))
    return a
def qa(q,a): return [P('Q. '+q,'Qx'),P('<b>Suggested response:</b> '+a,'Ax')]
def make_table(rows,widths,compact=False):
    t=Table(rows,colWidths=widths,repeatRows=1)
    pad=3 if compact else 5
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),PRIMARY),('BACKGROUND',(0,1),(-1,-1),BG),('GRID',(0,0),(-1,-1),.35,SURFACE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),pad),('BOTTOMPADDING',(0,0),(-1,-1),pad)]))
    return t
def footer(c,d):
    c.saveState(); w,h=letter; c.setStrokeColor(SURFACE); c.setLineWidth(.6); c.line(.62*inch,.5*inch,w-.62*inch,.5*inch); c.setFont('Helvetica',7.2); c.setFillColor(MUTED); c.drawString(.65*inch,.32*inch,'DaGOAL | Capstone Defense Reviewer | Prepared from application source code'); c.drawRightString(w-.65*inch,.32*inch,str(d.page)); c.restoreState()

