rows=[[P('Area','TH'),P('What the app implements','TH')],[P('Platform','TB'),P('Native Android app, Java source; min SDK 29, target SDK 36, version 1.0.','TB')],[P('Main experience','TB'),P('Onboarding/profile, avatar customization, daily quest reveal, dashboard with Quest, Wardrobe, Shop, and Me sections.','TB')],[P('Progression','TB'),P('Quest rewards feed local XP and gold; XP can advance levels. The app also tracks streaks, achievements, inventory, and clothing.','TB')],[P('Persistence','TB'),P('SQLite is the primary structured store; SharedPreferences stores onboarding/settings state. Firebase Authentication and selected Firestore features support accounts/cloud functions.','TB')],[P('Device integration','TB'),P('Step sensor foreground service; usage access plus overlay permission for app-avoidance quests; scheduled notification receiver.','TB')]]
