for h,b in [('1. Start and identify','“This is the DaGOAL Android application. It turns user goals into trackable quests and shows progression through rewards and avatar features.”'),('2. Show onboarding','Point out profile/questionnaire and avatar setup. Explain these represent user setup data; do not expose real user data.'),('3. Show daily quests','Open Quest. Explain target/current progress, quest type, and completion control. Complete a safe sample quest if the demo profile allows it.'),('4. Show rewards','Show XP, gold, level, achievements, or streak. Explain completion updates local progression state.'),('5. Show Wardrobe and Shop','Demonstrate owned/equipped items and purchase/reward flow only with demo data; mention online dependencies if relevant.'),('6. Explain optional tracking','Describe step-sensor or avoidance permissions. Demo live monitoring only if permissions are prepared and behavior is reliable on the test device.'),('7. Close on scope','Summarize what the app implements, then transition to study findings from the manuscript.')]: st += [P(h,'H2x'),P(b)]
st += [P('Before defense day: charge the demo device, turn off disruptive notifications, prepare a demo account, verify permissions and network-dependent features, keep screenshots/video as fallback, and rehearse a version that does not depend on live sensor/permission prompts.','Callout')]

