facts=[('Project title','[Exact approved capstone title]'),('Research problem','[Statement of the problem]'),('General objective','[Exact approved objective]'),('Specific objectives','[List and map to implemented/tested functions]'),('Target users / locale','[Who, where, inclusion criteria]'),('Research design','[Design and rationale]'),('Sampling / sample size','[Method, n, respondent profile]'),('Evaluation instrument','[Name, sections, validation/reliability]'),('Testing devices','[Models, OS versions, conditions]'),('Evaluation method/statistics','[Method and why appropriate]'),('Key findings','[Exact values, tables, interpretation]'),('Conclusion','[Conclusion supported by findings]'),('Limitations','[Research and technical limitations]'),('Ethics/data privacy','[Consent, data collected, storage, retention, approvals]'),('Future work','[Prioritized recommendation]')]
