st += [P('Final rehearsal checklist','H2x'),bullet('Every presenter can explain the purpose in 20 seconds.'),bullet('Everyone knows Activity purposes and which dashboard areas are not separate Activities.'),bullet('The team can trace quest generation/input through storage, reward calculation, and UI.'),bullet('Permission-dependent features and limitations are described accurately.'),bullet('Research design, participant, instrument, statistical, and result statements match the manuscript.'),bullet('Demo data is safe; account, permissions, network, and backup are ready.'),bullet('Presenters separate evidence from future plans.'),P('Source basis and scope','H2x'),P('Prepared from the DaGOAL Android project source, including AndroidManifest.xml, app/build.gradle.kts, Activity/service classes, TaskManager.java, DatabaseHelper.java, DatabaseContract.java, and relevant layouts/resources. This is a software walkthrough and defense-preparation aid, not a substitute for the approved capstone manuscript, ethics documentation, test logs, or study findings.','Smallx'),P('You are ready to explain what you built, show how users experience it, and defend the claims your evidence supports.','Callout')]

